* Calculate variables;

data var5;
set var4;
	LEV = (DLC + DLTT)/AT; /* Leverage */
	avgAT = (AT + AT_1)*0.5;
	AQI = ((AT-PPENT-ACT)-(AT_1-PPENT_1-ACT_1))/(avgAT); /* Change in intangibles */
	MV = PRCC_f*CSHO;
	MB = MV/CEQ; /* Market to book ratio */
	ROA = NI/avgAT; /* Return on assets */
	SIZE = log(AT); /* Size */
	CVAR_EMP = STDEMP/MEMP; /* Employee variability */
run;


* Lag variables;


proc sort data = var5;
	by GVKEY FYEAR;
run;

